"""离线 A4 姓名标签导出；使用本机已有 Python 和 ReportLab。"""
import csv
import io
import math
import os
from pathlib import Path
from reportlab.pdfgen import canvas
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.units import mm

ROOT = Path(__file__).resolve().parent
FONT = 'LocalChinese'


def register_font():
    if FONT not in pdfmetrics.getRegisteredFontNames():
        path = Path(os.environ.get('WINDIR', 'C:/Windows')) / 'Fonts/simhei.ttf'
        if not path.exists():
            raise ValueError('未找到本机黑体 simhei.ttf，无法可靠导出中文。')
        pdfmetrics.registerFont(TTFont(FONT, str(path)))


def parse(text):
    reader = csv.DictReader(io.StringIO(text.lstrip('\ufeff')))
    if not reader.fieldnames or not {'name', 'group', 'copies'}.issubset(reader.fieldnames):
        raise ValueError('CSV 表头必须包含 name,group,copies（可保留 id）。')
    rows = []
    for n, row in enumerate(reader, 2):
        if not any(v for v in row.values()):
            continue
        if None in row or any(row.get(k) is None for k in ('name', 'group', 'copies')):
            raise ValueError(f'第 {n} 行列数不正确。含逗号的文字请用双引号包围。')
        name, group = row['name'].strip(), row['group'].strip()
        if not name or not group:
            raise ValueError(f'第 {n} 行姓名、组别不能为空。')
        if any(ord(c) < 32 for c in name + group):
            raise ValueError(f'第 {n} 行含换行或控制字符，请改为单行文字。')
        try:
            count = int(row['copies'])
        except (TypeError, ValueError):
            raise ValueError(f'第 {n} 行 copies 必须为正整数。')
        if not 1 <= count <= 1000:
            raise ValueError(f'第 {n} 行 copies 须在 1～1000 之间。')
        rows.append({'name': name, 'group': group, 'copies': count})
    if not rows:
        raise ValueError('名单为空，请填写至少一人。')
    if sum(r['copies'] for r in rows) > 10000:
        raise ValueError('每批最多 10000 张，请分批导出。')
    register_font()
    for r in rows:
        for key, maximum in [('name', 28), ('group', 16)]:
            fit_size(r[key], maximum)
    return rows


def fit_size(text, maximum):
    font = pdfmetrics.getFont(FONT)
    missing = [c for c in text if ord(c) not in font.face.charToGlyph]
    if missing:
        raise ValueError('本机黑体不支持这些字符：' + ''.join(dict.fromkeys(missing)))
    width = pdfmetrics.stringWidth(text, FONT, maximum)
    size = min(maximum, 90 * mm / width * maximum) if width else maximum
    if size < 10:
        raise ValueError(f'文字过长，缩小后不足 10 磅：{text}。请缩短后再导出。')
    return size


def layout(rows):
    items = [r for r in rows for _ in range(r['copies'])]
    # Millimetres from the page's top left. All labels remain upright.
    return [(i // 4, 55, 21 + (i % 4) * 65, r) for i, r in enumerate(items)]


def export_pdf(rows, path):
    register_font()
    positions = layout(rows)
    pdf = canvas.Canvas(str(path), pagesize=(210 * mm, 297 * mm))
    pdf.setTitle('活动姓名标签 - A4竖向 - 100%打印')
    for page in range(math.ceil(len(positions) / 4)):
        for p, x, y, r in positions:
            if p != page:
                continue
            pdf.setStrokeColorRGB(.55, .55, .55)
            pdf.setLineWidth(.25)
            pdf.rect(x * mm, (297 - y - 60) * mm, 100 * mm, 60 * mm)
            pdf.setFillColorRGB(0, 0, 0)
            for key, maximum, baseline in [('name', 28, 27), ('group', 16, 43)]:
                pdf.setFont(FONT, fit_size(r[key], maximum))
                pdf.drawCentredString((x + 50) * mm, (297 - y - baseline) * mm, r[key])
        pdf.showPage()
    pdf.save()
    return len(positions), math.ceil(len(positions) / 4)


if __name__ == '__main__':
    import argparse
    parser = argparse.ArgumentParser(description='离线导出 A4 竖向姓名标签 PDF')
    parser.add_argument('--input', type=Path, default=ROOT/'inputs/名单.csv')
    parser.add_argument('--output', type=Path, default=ROOT/'outputs/活动姓名标签.pdf')
    args = parser.parse_args()
    target = args.output.resolve()
    if not target.is_relative_to(ROOT) or target.is_relative_to(ROOT/'inputs'):
        parser.error('输出须位于当前工具目录内，且不能写入 inputs。')
    data = args.input.read_bytes()
    try:
        text = data.decode('utf-8-sig')
    except UnicodeDecodeError:
        text = data.decode('gb18030')
    count, pages = export_pdf(parse(text), target)
    print(f'已导出 {count} 张 / {pages} 页：{target}')

