"""离线名字标签 PDF 命令行导出。使用本机 Python 和 ReportLab。"""
import csv
import io
import math
import os
from pathlib import Path
import sys
from reportlab.pdfgen import canvas
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.units import mm

ROOT = Path(__file__).resolve().parent
FONT = 'LocalChinese'

def local_path(path):
    path=Path(path).resolve()
    if not path.is_relative_to(ROOT):
        raise ValueError('请在本工具所在目录内选择文件，以遵守仅在当前工作目录操作的限制')
    if path.is_relative_to(ROOT/'inputs'):
        raise ValueError('inputs 为原文件目录，请在工具目录另存成果')
    return path

def load_font():
    if FONT not in pdfmetrics.getRegisteredFontNames():
        pdfmetrics.registerFont(TTFont(FONT, 'C:/Windows/Fonts/simsun.ttc', subfontIndex=0))

def parse(text):
    reader = csv.DictReader(io.StringIO(text.lstrip('\ufeff')))
    if reader.fieldnames != ['id', 'name', 'group', 'copies']:
        raise ValueError('表头必须为 id,name,group,copies（顺序相同）')
    result, ids = [], set()
    for line, row in enumerate(reader, 2):
        if None in row or any(v is None for v in row.values()):
            raise ValueError(f'第 {line} 行列数不正确')
        row = {k:v.strip() for k,v in row.items()}
        if any(not v for v in row.values()):
            raise ValueError(f'第 {line} 行有空字段')
        if row['id'] in ids:
            raise ValueError(f'第 {line} 行编号重复；同名人员请使用不同编号')
        ids.add(row['id'])
        if not row['copies'].isascii() or not row['copies'].isdigit() or not 1 <= int(row['copies']) <= 1000:
            raise ValueError(f'第 {line} 行份数须为 1–1000 的整数')
        for key in ('name','group'):
            if any(ord(c)<32 or ord(c)>65535 for c in row[key]):
                raise ValueError(f'第 {line} 行包含不支持的控制符或扩展字符，请改用常用汉字/文字')
        result.extend([row.copy() for _ in range(int(row['copies']))])
        if len(result)>5000:
            raise ValueError('一次最多生成 5000 张，请拆分名单')
    if not result:
        raise ValueError('名单为空，请添加人员')
    return result

def slots():
    # 枚举 A4 两种方向、每层两种标签方向；完整保留尺寸与间隙。
    options=[]
    for pw,ph in [(210,297),(297,210)]:
        def visit(rows, height):
            if rows:
                options.append((sum(r[0] for r in rows),pw,ph,rows[:]))
            for w,h,rot in [(100,60,False),(60,100,True)]:
                count=int((pw-20+5)//(w+5))
                new=height+(5 if rows else 0)+h
                if new<=ph-20:
                    visit(rows+[(count,w,h,rot)],new)
        visit([],0)
    return options

def layout(items):
    options=slots()
    # 先最少页数，再少空位，再优先竖纸及不旋转。
    count,pw,ph,rows=min(options,key=lambda p:(math.ceil(len(items)/p[0]), (p[0]-len(items)%p[0])%p[0],p[1],sum(r[3] for r in p[3])))
    positions=[]
    y=10
    for n,w,h,rot in rows:
        for col in range(n):
            positions.append((10+col*(w+5),y,w,h,rot))
        y+=h+5
    pages=[]
    for start in range(0,len(items),count):
        pages.append([(item,*pos) for item,pos in zip(items[start:start+count],positions)])
    return pw,ph,pages

def font_size(text, preferred, width):
    size=min(preferred,width/pdfmetrics.stringWidth(text,FONT,1))
    if size<9:
        raise ValueError(f'“{text}”太长，字号将小于 9 磅；请缩短后再导出')
    return size

def validated(text):
    load_font()
    items=parse(text)
    for item in items:
        for key in ('name','group'):
            missing=[ch for ch in item[key] if ord(ch) not in pdfmetrics.getFont(FONT).face.charToGlyph]
            if missing:
                raise ValueError('本机宋体缺少这些字符：'+''.join(missing)+'；请替换为可显示文字')
        font_size(item['name'],30,90*mm)
        font_size(item['group'],16,90*mm)
    return items,layout(items)

def export_pdf(text, path):
    items,(pw,ph,pages)=validated(text)
    # 先全部校验，再写文件；临时文件成功后替换目标。
    path=local_path(path)
    temp=path.with_name(path.name+'.tmp')
    try:
        c=canvas.Canvas(str(temp),pagesize=(pw*mm,ph*mm))
        c.setTitle('社团活动名字标签')
        for page in pages:
            for item,x,y,w,h,rot in page:
                c.saveState()
                c.translate(x*mm,(ph-y-h)*mm)
                c.setLineWidth(.2*mm)
                c.setStrokeColorRGB(.55,.55,.55)
                # 裁切框外缘恰好是标签尺寸，笔画全部位于标签内。
                c.rect(.1*mm,.1*mm,(w-.2)*mm,(h-.2)*mm)
                if rot:
                    c.translate(0,100*mm)
                    c.rotate(-90)
                c.setFillColorRGB(0,0,0)
                for key,base,ypos in [('name',30,32),('group',16,17)]:
                    c.setFont(FONT,font_size(item[key],base,90*mm))
                    c.drawCentredString(50*mm,ypos*mm,item[key])
                c.restoreState()
            c.showPage()
        c.save()
        os.replace(temp,path)
    finally:
        if temp.exists(): temp.unlink()
    return len(items),len(pages)

if __name__=='__main__':
    if len(sys.argv)==4 and sys.argv[1]=='--export':
        print(export_pdf(Path(sys.argv[2]).read_text(encoding='utf-8-sig'),sys.argv[3]))
    else:
        print('Usage: python label_tool.py --export INPUT.csv OUTPUT.pdf')

